using XianXia.Common.Systems;
int assertions=0;void Check(bool ok,string text){assertions++;if(!ok)throw new Exception(text);}
(string Name,int Life,int Damage)[] expected=[("SpiritVeinWyrm",1200,22),("GardenWarden",2800,28),("BlackFurnaceIronGolem",3200,34),("TribulationCloudAvatar",4200,30),("ThunderMarshJiao",18000,58),("AbyssalStarWomb",21000,54),("FormlessSwordSoul",48000,72),("GreenwoodMedicineKingEcho",52000,66),("HeavenTabletGuardian",86000,82),("BrokenHeavenInspector",96000,92),("MoonboneImmortal",420000,180),("OldHeavenDaoCore",650000,220)];
foreach(var e in expected){var stats=BossStatRules.Get(e.Name);Check(stats==(e.Life,e.Damage),"Preserve ordinary baseline");foreach(int nativeMultiplier in new[]{1,2,3}){int life=e.Life*nativeMultiplier;Check(BossStatRules.ScaleLife(life,1,1)==life,"Do not apply another difficulty multiplier");Check(BossStatRules.ScaleLife(life,1.5f,1)==life*1.5,"Provided player balance applies once");Check(BossStatRules.ScaleLife(life,2.5f,.8f)==(int)(life*2.5d*(double).8f),"Respect supplied boss adjustment");}}
foreach(float factor in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity,0f,-1f}){Check(BossStatRules.ScaleLife(100,factor,1)==100,"Invalid balance fallback");Check(BossStatRules.ScaleLife(100,1,factor)==100,"Invalid adjustment fallback");}
Check(BossStatRules.ScaleLife(int.MaxValue,float.MaxValue,float.MaxValue)==int.MaxValue,"Overflow clamp");Check(BossStatRules.ScaleLife(0,1,1)==1&&BossStatRules.ScaleLife(-20,1,1)==1,"Positive life invariant");Check(BossStatRules.ScaleLife(101,1.5f,1)==151,"Integer truncation");
try{BossStatRules.Get("Unknown");throw new Exception("Unknown boss accepted");}catch(ArgumentException){assertions++;}
Console.WriteLine($"Boss scaling rules passed: {assertions} assertions. Inputs simulate engine scaling; not an in-game difficulty matrix.");
